export interface CopilotChatPayload {
  messages: Array<{
    role: 'user' | 'assistant';
    text: string;
    attachments?: Array<{
      name: string;
      type: string;
      base64?: string;
    }>;
  }>;
  pageContext?: {
    currentQuery: string;
    selectedSources: AcademicSource[];
    semanticMode: boolean;
    openAccessOnly: boolean;
    hasPdfOnly: boolean;
    totalFound: number;
    resultsCount: number;
    activeArticleTitle?: string | null;
    savedCount: number;
  };
}

export async function handleCopilotChat(payload: CopilotChatPayload | CopilotChatPayload['messages']): Promise<{
  text: string;
  articles?: UnifiedArticle[];
  editais?: UnilaEdital[];
  actions?: CopilotAction[];
}> {
  const messages = Array.isArray(payload) ? payload : (payload?.messages || []);
  const pageContext = Array.isArray(payload) ? undefined : payload?.pageContext;
  const lastMessage = messages[messages.length - 1];

  if (!lastMessage || !lastMessage.text.trim()) {
    return {
      text: "Olá! Sou Sophia, a Inteligência Artificial e Co-pilot Científica da Busca Acadêmica Integrada UNILA. Como posso te auxiliar em sua pesquisa, busca de artigos ou informações sobre a UNILA e editais hoje?"
    };
  }

  // 1. Tentar executar via provedores LLM configurados (Gemini, Groq, OpenAI, OpenRouter)
  const llmResult = await tryExecuteLlmProvider(messages, pageContext);
  if (llmResult) {
    return llmResult;
  }

  // 2. Motor Dinâmico Baseado em APIs Reais (UNILA Editais API, Harvester Acadêmico, UNILA News API e Wikipedia/Crossref API)
  // Gera respostas 100% dinâmicas sem respostas prontas ou estáticas.
  return handleDynamicApiEngine(messages, pageContext);
}

/**
 * Executa requisição via Gemini API (cotas gratuitas do AI Studio)
 */
async function tryExecuteLlmProvider(
  messages: CopilotChatPayload['messages'],
  pageContext?: CopilotChatPayload['pageContext']
): Promise<{
  text: string;
  articles?: UnifiedArticle[];
  editais?: UnilaEdital[];
  actions?: CopilotAction[];
} | null> {
  const ai = getAiClient();
  if (!ai) return null;

  try {
    const contents: any[] = [];
    const contextSummary = pageContext 
      ? `[Contexto da página: Busca="${pageContext.currentQuery || 'Nenhuma'}", Resultados=${pageContext.resultsCount}, OA=${pageContext.openAccessOnly}, PDF=${pageContext.hasPdfOnly}, Salvos=${pageContext.savedCount}]`
      : '';

    for (let i = 0; i < messages.length; i++) {
      const msg = messages[i];
      const parts: any[] = [];
      if (i === messages.length - 1 && contextSummary) {
        parts.push({ text: `${contextSummary}\n\n${msg.text}` });
      } else {
        parts.push({ text: msg.text });
      }

      if (msg.attachments && msg.attachments.length > 0) {
        for (const att of msg.attachments) {
          if (att.base64 && att.type) {
            parts.push({
              inlineData: {
                mimeType: att.type,
                data: att.base64.replace(/^data:[^;]+;base64,/, '')
              }
            });
          }
        }
      }

      contents.push({
        role: msg.role === 'assistant' ? 'model' : 'user',
        parts
      });
    }

    // Modelos Gemini com suporte a cotas gratuitas e rápida resposta
    const candidateModels = ['gemini-3.8-flash', 'gemini-3.1-flash-lite', 'gemini-flash-latest'];
    for (let attempt = 0; attempt < 3; attempt++) {
      const model = candidateModels[attempt % candidateModels.length];
      try {
        const response = await ai.models.generateContent({
          model,
          contents,
          config: {
            systemInstruction: SYSTEM_INSTRUCTION,
            tools: COPILOT_TOOLS,
            temperature: 0.7
          }
        });

        if (response) {
          return await processLlmToolCallsAndResponse(ai, model, contents, response);
        }
      } catch (callErr: any) {
        console.warn(`Tentativa ${attempt + 1} (${model}) falhou (${callErr?.status || callErr?.message}). Alternando modelo...`);
        if (attempt < 2) {
          await new Promise(r => setTimeout(r, 400 * (attempt + 1)));
        }
      }
    }
  } catch (err: any) {
    console.error("Erro no provedor LLM:", err);
  }

  return null;
}

/**
 * Processa chamadas de função retornadas pela LLM e executa o Turno 2
 */
async function processLlmToolCallsAndResponse(
  ai: GoogleGenAI,
  activeModel: string,
  contents: any[],
  response: any
): Promise<{
  text: string;
  articles?: UnifiedArticle[];
  editais?: UnilaEdital[];
  actions?: CopilotAction[];
}> {
  const actions: CopilotAction[] = [];
  let retrievedArticles: UnifiedArticle[] = [];
  let retrievedEditais: UnilaEdital[] = [];
  let assistantText = response.text || '';

  const candidates = response.candidates || [];
  const candidateContent = candidates[0]?.content;
  const functionCalls: any[] = [];
  for (const cand of candidates) {
    for (const part of cand.content?.parts || []) {
      if (part.functionCall) {
        functionCalls.push(part.functionCall);
      }
    }
  }

  if (functionCalls.length > 0) {
    const functionResponses: any[] = [];

    for (const call of functionCalls) {
      const { name, args } = call;

      if (name === 'search_academic_repositories') {
        const query = (args?.query as string) || '';
        const limit = typeof args?.limit === 'number' ? args.limit : 4;
        try {
          const searchRes = await executeFederatedSearch(
            query,
            ['OpenAlex', 'arXiv', 'DOAJ', 'Europe PMC', 'Crossref', 'Semantic Scholar', 'CORE'],
            true
          );
          retrievedArticles = searchRes.articles.slice(0, limit);
          actions.push({
            type: 'HIGHLIGHT_ELEMENT',
            description: `Pesquisou artigos para: "${query}"`,
            payload: {
              elementId: 'results-feed-column',
              title: 'Artigos Encontrados',
              description: `Encontrei ${searchRes.articles.length} publicações indexadas nas bases.`
            }
          });
          functionResponses.push({
            functionResponse: {
              name,
              response: {
                totalFound: searchRes.articles.length,
                query,
                displayedCount: retrievedArticles.length,
                articles: retrievedArticles.map(a => ({
                  title: a.title,
                  authors: a.authors.slice(0, 3).map(au => au.name).join(', '),
                  year: a.year,
                  sources: a.sources.join(', '),
                  hasPdf: Boolean(a.openAccess?.pdfUrl || a.urls?.pdfUrl)
                }))
              }
            }
          });
        } catch (searchErr: any) {
          console.error("Co-pilot search error:", searchErr);
          functionResponses.push({
            functionResponse: { name, response: { error: "Falha na busca acadêmica", query } }
          });
        }
      } else if (name === 'search_unila_editais') {
        const query = (args?.query as string) || '';
        const category = args?.category as string;
        try {
          const editais = await fetchUnilaEditais(query, category, 6);
          retrievedEditais = editais;
          actions.push({
            type: 'HIGHLIGHT_ELEMENT',
            description: 'Consultou Editais Oficiais da UNILA',
            payload: {
              elementId: 'institutional-horizontal-nav',
              title: 'Editais Oficiais UNILA',
              description: 'Link oficial para consulta no portal institucional.'
            }
          });
          functionResponses.push({
            functionResponse: {
              name,
              response: {
                totalFound: editais.length,
                query,
                editais: editais.map(e => ({
                  title: e.title,
                  category: e.category,
                  unit: e.unit,
                  publishDate: e.publishDate
                }))
              }
            }
          });
        } catch (edErr: any) {
          console.error("Co-pilot editais error:", edErr);
          functionResponses.push({
            functionResponse: { name, response: { error: "Falha na consulta de editais", query } }
          });
        }
      } else if (name === 'highlight_element') {
        actions.push({
          type: 'HIGHLIGHT_ELEMENT',
          description: `Destacou: ${args?.title || args?.elementId}`,
          payload: {
            elementId: args?.elementId,
            title: args?.title || 'Destaque',
            description: args?.description || ''
          }
        });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, highlightedElement: args?.elementId }
          }
        });
      } else if (name === 'execute_page_search') {
        actions.push({
          type: 'EXECUTE_SEARCH',
          description: `Pesquisando por "${args?.query}"`,
          payload: {
            query: args?.query,
            semantic: args?.semantic,
            openAccessOnly: args?.openAccessOnly,
            hasPdfOnly: args?.hasPdfOnly
          }
        });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, executedQuery: args?.query }
          }
        });
      } else if (name === 'filter_page_results') {
        if (args?.openAccessOnly !== undefined) {
          actions.push({
            type: 'SET_OPEN_ACCESS',
            description: args.openAccessOnly ? 'Ativou Acesso Aberto' : 'Desativou Acesso Aberto',
            payload: { value: args.openAccessOnly }
          });
        }
        if (args?.hasPdfOnly !== undefined) {
          actions.push({
            type: 'SET_HAS_PDF',
            description: args.hasPdfOnly ? 'Ativou PDF Direto' : 'Desativou PDF Direto',
            payload: { value: args.hasPdfOnly }
          });
        }
        if (args?.semanticMode !== undefined) {
          actions.push({
            type: 'SET_SEMANTIC_MODE',
            description: args.semanticMode ? 'Ativou Busca Semântica' : 'Desativou Busca Semântica',
            payload: { value: args.semanticMode }
          });
        }
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, updatedFilters: args }
          }
        });
      } else if (name === 'open_view') {
        if (args?.view === 'saved') actions.push({ type: 'OPEN_SAVED' });
        else if (args?.view === 'methodology') actions.push({ type: 'OPEN_METHODOLOGY' });
        else if (args?.view === 'sources') actions.push({ type: 'OPEN_SOURCES_STATUS' });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, openedView: args?.view }
          }
        });
      } else if (name === 'guide_platform_tour') {
        actions.push({
          type: 'START_TOUR',
          payload: { tourTopic: args?.tourTopic || 'geral' }
        });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, startedTour: args?.tourTopic }
          }
        });
      }
    }

    // Turno 2: A IA formula a resposta explicativa com base nas informações retornadas
    if (candidateContent && functionResponses.length > 0) {
      try {
        const turn2Res = await ai.models.generateContent({
          model: activeModel,
          contents: [
            ...contents,
            candidateContent,
            {
              role: 'user',
              parts: functionResponses
            }
          ],
          config: {
            systemInstruction: SYSTEM_INSTRUCTION
          }
        });

        if (turn2Res && turn2Res.text) {
          assistantText = turn2Res.text;
        }
      } catch (turn2Err: any) {
        console.warn("Turno 2 da IA finalizado com síntese contextualizada:", turn2Err?.message);
      }
    }
  }

  // Síntese dinâmica caso o modelo não tenha emitido texto final
  if (!assistantText) {
    if (retrievedEditais.length > 0) {
      assistantText = `Consultei o portal oficial de documentos e editais da UNILA e selecionei ${retrievedEditais.length} editais relevantes para você. Veja as opções para consulta e download abaixo:`;
    } else if (retrievedArticles.length > 0) {
      assistantText = `Encontrei ${retrievedArticles.length} publicações acadêmicas diretamente nas bases científicas integradas. Você pode visualizar os resumos e abrir os PDFs a seguir:`;
    } else if (actions.length > 0 && actions[0].description) {
      assistantText = `${actions[0].description} diretamente na tela da plataforma!`;
    } else {
      assistantText = "Ação executada com sucesso na interface.";
    }
  }

  return {
    text: assistantText,
    articles: retrievedArticles.length > 0 ? retrievedArticles : undefined,
    editais: retrievedEditais.length > 0 ? retrievedEditais : undefined,
    actions: actions.length > 0 ? actions : undefined
  };
}

/**
 * Motor Dinâmico Baseado em APIs Reais
 * Zero respostas prontas: toda resposta consulta APIs em tempo real (UNILA Editais, Harvester, Portal News, Wikipedia API)
 */
async function handleDynamicApiEngine(
  messages: CopilotChatPayload['messages'],
  pageContext?: CopilotChatPayload['pageContext']
): Promise<{
  text: string;
  articles?: UnifiedArticle[];
  editais?: UnilaEdital[];
  actions?: CopilotAction[];
}> {
  const lastMessage = messages[messages.length - 1];
  const prompt = (lastMessage?.text || '').trim();
  const lower = prompt.toLowerCase();
  const norm = normalizeText(prompt);
  const actions: CopilotAction[] = [];

  // 1. Saudações e Cumprimentos Acolhedores (Oi, Olá, Bom dia, etc.)
  const greetingExact = [
    "oi", "ola", "oie", "opa", "e ai", "eai", "salve", "hey", "hello", "hi", 
    "saudacoes", "hola", "buenos dias", "buenas tardes", "buenas noches", "saludos",
    "oi sophia", "ola sophia", "oie sophia", "ola sophia tudo bem", "oi tudo bem"
  ];
  const isDirectGreeting = 
    greetingExact.includes(norm) ||
    /^(oi|ola|oie|opa|e ai|eai|salve|hey|hello|hi|saudacoes|hola)\s+(sophia|amiga|pessoal|bot|ia|tudo bem|como vai|bom dia|boa tarde|boa noite)/i.test(norm) ||
    /^(bom dia|boa tarde|boa noite)(!|\?|\s+sophia|\s+tudo bem|\s+como vai)?$/i.test(norm) ||
    norm === 'oi' || norm === 'ola' || norm === 'oie' || norm === 'opa';

  if (isDirectGreeting) {
    let greetingHeader = "Olá! Seja muito bem-vindo(a) ao **Multirrepositório Acadêmico da UNILA**! 👋";
    if (norm.includes('bom dia')) {
      greetingHeader = "Bom dia! Seja muito bem-vindo(a) à plataforma de pesquisa científica da UNILA! ☀️";
    } else if (norm.includes('boa tarde')) {
      greetingHeader = "Boa tarde! Que bom ter você por aqui no Multirrepositório da UNILA! 🌤️";
    } else if (norm.includes('boa noite')) {
      greetingHeader = "Boa noite! Espero que sua jornada de pesquisa esteja sendo proveitosa! 🌙";
    } else if (norm.includes('hola') || norm.includes('buenos dias') || norm.includes('buenas tardes') || norm.includes('saludos')) {
      greetingHeader = "¡Hola! ¡Te doy una cordial bienvenida al **Multirrepositorio Académico de la UNILA**! 🤝";
    }

    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'search-bar-input',
        title: 'Pesquisa Acadêmica UNILA',
        description: 'Digite termos de busca, autores ou DOI para iniciar uma pesquisa.'
      }
    });

    const isSpanish = norm.includes('hola') || norm.includes('buenos dias') || norm.includes('buenas tardes') || norm.includes('saludos');

    if (isSpanish) {
      return {
        text: `${greetingHeader}\n\n` +
          `Soy **Sophia**, tu copiloto de investigación científica oficial. Como universidad de integración latinoamericana, aquí trabajamos en español y portugués.\n\n` +
          `Puedo ayudarte a:\n` +
          `- 🔍 **Buscar artículos científicos** indexados en 8 bases académicas globales (OpenAlex, arXiv, Crossref, DOAJ, Europe PMC, etc.);\n` +
          `- 📋 **Consultar convocatorias y edictos oficiales de la UNILA** (posgrados, maestrías, doctorados, becas PIBIC);\n` +
          `- 📄 **Filtrar publicaciones con PDF directo** y en **Acceso Abierto (Open Access)**;\n` +
          `- 🧭 **Aprender a usar los recursos de la plataforma** y destacar herramientas en pantalla.\n\n` +
          `¿En qué puedo colaborar con tu investigación hoy?`,
        actions
      };
    }

    return {
      text: `${greetingHeader}\n\n` +
        `Sou a **Sophia**, sua inteligência artificial e copiloto de pesquisa científica na UNILA.\n\n` +
        `Estou aqui para colaborar com você em cada etapa da sua produção acadêmica:\n` +
        `- 🔍 **Pesquisar artigos científicos reais** em 8 bases globais unificadas com desduplicação por DOI;\n` +
        `- 📋 **Consultar editais oficiais e processos seletivos da UNILA** (mestrados, doutorados, bolsas PIBIC, PAPADE);\n` +
        `- 📄 **Localizar publicações com PDF direto** e em **Acesso Aberto (Open Access)** sem barreiras de paywall;\n` +
        `- 🧭 **Orientar na navegação da interface** (destacar botões, filtros facetados, coleção de artigos salvos e exportação BibTeX/RIS).\n\n` +
        `Como posso te apoiar nos seus estudos ou na sua pesquisa hoje?`,
      actions
    };
  }

  // 2. Perguntas de Bem-Estar e Cortesia ("Tudo bem?", "Como vai?", etc.)
  const isCourtesyStatus = 
    norm === "tudo bem" || 
    norm === "tudo bom" || 
    norm === "como vai" || 
    norm === "como voce esta" || 
    norm === "como estao as coisas" || 
    norm === "beleza" || 
    norm === "tudo certo" || 
    /^(tudo bem|tudo bom|como vai|como voce esta)\b/.test(norm);

  if (isCourtesyStatus) {
    return {
      text: "Tudo ótimo por aqui, muito obrigada por perguntar! 😊 Sempre entusiasmada em conectar pesquisadores ao conhecimento científico e acompanhar a produção acadêmica da UNILA.\n\n" +
        "E com você, como estão os estudos e projetos de pesquisa? Tem algum tema, artigo ou edital em que eu possa te dar uma força hoje?",
      actions: [{
        type: 'HIGHLIGHT_ELEMENT',
        payload: {
          elementId: 'search-bar-input',
          title: 'Iniciar Busca Acadêmica',
          description: 'Pronto para pesquisar? Digite seu tema aqui.'
        }
      }]
    };
  }

  // 3. Perguntas sobre Identidade e Funções da Sophia ("Quem é você?", "O que você faz?")
  const isIdentityQuestion = 
    norm.includes("quem e voce") || 
    norm.includes("quem e sophia") || 
    norm.includes("o que voce faz") || 
    norm.includes("qual seu nome") || 
    norm.includes("qual e o seu nome") || 
    norm.includes("voce e um robo") || 
    norm.includes("voce e uma ia") || 
    norm.includes("voce e inteligencia artificial") || 
    norm.includes("se apresente") || 
    norm.includes("apresente se") ||
    norm.includes("o que e sophia") ||
    norm.includes("como voce pode me ajudar");

  if (isIdentityQuestion) {
    return {
      text: "Sou a **Sophia**, a Inteligência Artificial e Co-pilot Científica Oficial do **Multirrepositório Acadêmico da UNILA** (Universidade Federal da Integração Latino-Americana). 🎓\n\n" +
        "Meu propósito é atuar como parceira de pesquisa para a comunidade acadêmica — estudantes de graduação, pós-graduandos, docentes e pesquisadores.\n\n" +
        "### No que posso te ajudar:\n" +
        "1. 🔬 **Busca Federada em 8 Bases Acadêmicas**: Consulto em tempo real OpenAlex, arXiv, Crossref, DOAJ, Europe PMC, Semantic Scholar, CORE e Portal de Periódicos CAPES, unificando e desduplicando artigos por DOI canônico.\n" +
        "2. 📋 **Editais Oficiais da UNILA**: Conecto-me diretamente ao sistema de documentos da UNILA (`documentos.unila.edu.br` e `portal.unila.edu.br/editais`) para exibir processos seletivos vigentes (mestrado, doutorado, bolsas PIBIC/PIBITI, auxílios PAPADE).\n" +
        "3. 📰 **Notícias Institucionais**: Acompanho o portal da universidade (`portal.unila.edu.br`) trazendo novidades, eventos e comunicados.\n" +
        "4. 🧭 **Controle e Navegação Visual**: Se você perguntar *'onde fica o filtro de acesso aberto?'* ou *'onde vejo os artigos salvos?'*, eu acendo e destaco os elementos na tela para você!\n" +
        "5. 📄 **Acesso Aberto & PDFs**: Identifico publicações sem paywall com links diretos para leitura.\n\n" +
        "Fique à vontade para me perguntar qualquer coisa sobre sua pesquisa ou sobre a UNILA!",
      actions: [{
        type: 'HIGHLIGHT_ELEMENT',
        payload: {
          elementId: 'search-bar-input',
          title: 'Barra de Pesquisa Acadêmica',
          description: 'Sua porta de entrada para a literatura científica global.'
        }
      }]
    };
  }

  // 4. Agradecimentos e Cortesia ("Obrigado", "Valeu", "Excelente", etc.)
  const isThankYou = 
    norm.includes("obrigado") || 
    norm.includes("obrigada") || 
    norm.includes("valeu") || 
    norm.includes("gracias") || 
    norm.includes("muito bom") || 
    norm.includes("perfeito") || 
    norm.includes("maravilha") || 
    norm.includes("otimo") || 
    norm.includes("excelente") || 
    norm.includes("show de bola") || 
    norm.includes("ajudou muito");

  if (isThankYou) {
    return {
      text: "Disponha sempre! É uma alegria poder contribuir com seus estudos e descobertas. 😊\n\n" +
        "Se quiser refinar sua busca, conferir outros autores, verificar novos editais da UNILA ou exportar as referências em BibTeX/RIS, conte comigo a qualquer momento. Boas pesquisas!",
    };
  }

  // 5. Despedidas ("Tchau", "Até mais", "Até logo", etc.)
  const isFarewell = 
    norm === "tchau" || 
    norm === "ate mais" || 
    norm === "ate logo" || 
    norm === "falou" || 
    norm === "fui" || 
    norm === "ate amanha" || 
    norm === "adios" || 
    norm === "adeus" || 
    norm === "hasta luego";

  if (isFarewell) {
    return {
      text: "Até logo! Desejo muito sucesso na sua caminhada acadêmica e em suas pesquisas na UNILA. Quando precisar de apoio com a literatura científica ou editais, estarei por aqui. Até a próxima! 👋✨",
    };
  }

  // 6. Informações Institucionais sobre a UNILA ("O que é a UNILA?", "Onde fica?", etc.)
  const isUnilaInfo = 
    norm.includes("o que e a unila") || 
    norm.includes("o que e unila") || 
    norm.includes("fale sobre a unila") || 
    norm.includes("fale da unila") || 
    norm.includes("sobre a unila") || 
    norm.includes("onde fica a unila") || 
    norm.includes("historia da unila") || 
    norm.includes("missao da unila");

  if (isUnilaInfo) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'institutional-horizontal-nav',
        title: 'Navegação Institucional UNILA',
        description: 'Atalhos oficiais para o portal institucional, editais e biblioteca da UNILA.'
      }
    });

    return {
      text: "A **UNILA** (Universidade Federal da Integração Latino-Americana) é uma universidade pública federal brasileira, criada em 2010 (Lei nº 12.189) e sediada em **Foz do Iguaçu, Paraná**, na região estratégica da Tríplice Fronteira (Brasil, Argentina e Paraguai). 🌎\n\n" +
        "### Pilares Institucionais:\n" +
        "- **Integração Latino-Americana e Caribenha**: Sua missão central é formar recursos humanos para impulsionar a integração solidária, científica e cultural dos povos da América Latina e do Caribe.\n" +
        "- **Bilinguismo e Multiculturalidade**: O português e o espanhol são línguas acadêmicas oficiais, reunindo docentes e estudantes de dezenas de nacionalidades.\n" +
        "- **Institutos Interdisciplinares**:\n" +
        "  - **ILATAC**: Tecnologia, Infraestrutura e Território;\n" +
        "  - **ILACVN**: Ciências da Vida e da Natureza;\n" +
        "  - **ILAESP**: Economia, Sociedade e Política;\n" +
        "  - **ILAACH**: Arte, Cultura e História.\n\n" +
        "Acesse o portal oficial em [portal.unila.edu.br](https://portal.unila.edu.br/) e confira os editais abertos em [portal.unila.edu.br/editais](https://portal.unila.edu.br/editais). Deseja consultar editais ou notícias recentes da universidade?",
      actions
    };
  }

  // 7. Tutorial e Como Usar a Plataforma ("Como funciona?", "Como pesquisar?", "Ajuda")
  const isHowToUse = 
    norm.includes("como funciona a plataforma") || 
    norm.includes("como pesquisar na plataforma") || 
    norm.includes("como usar a plataforma") || 
    norm.includes("como usar o site") || 
    norm.includes("tutorial da plataforma") || 
    norm.includes("o que posso pesquisar aqui") ||
    norm === "ajuda" ||
    norm === "me ajuda" ||
    norm === "preciso de ajuda";

  if (isHowToUse) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'search-bar-input',
        title: 'Barra de Pesquisa Acadêmica',
        description: 'Digite termos de busca, temas ou DOI para iniciar.'
      }
    });

    return {
      text: "É muito simples e intuitivo pesquisar no **Multirrepositório Acadêmico da UNILA**! Veja o passo a passo:\n\n" +
        "1. 🔍 **Barra de Pesquisa Central**: Digite temas científicos (ex: *'energias renováveis'*, *'agroecologia'*), nomes de autores ou códigos DOI. Pressione Enter ou clique na lupa.\n" +
        "2. 🧠 **Modo Semântico IA**: Ative o botão 'Busca Semântica' para expandir automaticamente sinônimos contextuais além de correspondências literais.\n" +
        "3. 🌐 **Seletor de 8 Bases**: Logo abaixo da busca, você pode ligar ou desligar fontes específicas (OpenAlex, arXiv, Crossref, DOAJ, Europe PMC, Semantic Scholar, CORE, CAPES).\n" +
        "4. 🔓 **Acesso Aberto & PDF Direto**: Use os seletores rápidos para exibir apenas trabalhos de leitura livre ou apenas com download imediato de PDF.\n" +
        "5. 📊 **Filtros Laterais**: Filtre os resultados por faixa de anos, autores frequentes e áreas de conhecimento.\n" +
        "6. ⭐ **Salvar & Exportar**: Marque artigos com a estrela para reuni-los na sua **Coleção Salva** e exportar tudo em BibTeX ou RIS para o Zotero/Mendeley.\n\n" +
        "Se quiser, pode me pedir: *'onde fica o filtro de acesso aberto?'*, *'mostre os editais da UNILA'* ou *'busque artigos sobre biodiversidade'*!",
      actions
    };
  }

  // 8. Solicitação de Editais da UNILA (https://portal.unila.edu.br/editais e documentos.unila.edu.br)
  const isEditalQuery = 
    lower.includes('edital') || 
    lower.includes('editais') || 
    lower.includes('processo seletivo') || 
    lower.includes('inscriç') || 
    lower.includes('bolsa') || 
    lower.includes('vaga') || 
    lower.includes('pape') || 
    lower.includes('papade') || 
    lower.includes('pibic') || 
    lower.includes('pibiti') || 
    lower.includes('concurso');

  if (isEditalQuery) {
    // Consulta em tempo real via API do sistema de editais da UNILA
    const stopWords = [
      'edital', 'editais', 'unila', 'mostre', 'exiba', 'quais', 'os', 'as', 'tem',
      'sobre', 'recentes', 'recente', 'novos', 'novo', 'atual', 'atuais', 'vigentes',
      'vigente', 'oficiais', 'oficial', 'para', 'com', 'por', 'favor', 'da', 'do', 'de', 'no', 'na'
    ];
    const queryTerm = extractSearchKeywords(lower, stopWords);
    let editais = await fetchUnilaEditais(queryTerm, undefined, 6);

    // Se a busca com o termo restrito não retornar nada, recupera os editais oficiais mais recentes
    if (editais.length === 0 && queryTerm) {
      editais = await fetchUnilaEditais('', undefined, 6);
    }

    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      description: 'Destacou acesso a Editais no cabeçalho institucional',
      payload: {
        elementId: 'institutional-horizontal-nav',
        title: 'Editais Oficiais UNILA',
        description: 'Link direto no cabeçalho institucional para o portal de editais (https://portal.unila.edu.br/editais).'
      }
    });

    let text = `Consultei em tempo real o sistema oficial de documentos e editais da **UNILA** (https://documentos.unila.edu.br e https://portal.unila.edu.br/editais). `;
    if (editais.length > 0) {
      text += `Encontrei **${editais.length} editais oficiais** disponíveis para visualização e download:\n\n`;
      for (const ed of editais.slice(0, 4)) {
        text += `- **Edital Nº ${ed.number}/${ed.year} (${ed.unit})**: ${ed.title.slice(0, 140)}... *Publicado em ${ed.publishDate}*. [Acessar documento oficial](${ed.url})\n`;
      }
      text += `\nVocê pode clicar nos cartões interativos abaixo para acessar o documento completo na íntegra.`;
    } else {
      text += `Acesse diretamente o portal de editais em [portal.unila.edu.br/editais](https://portal.unila.edu.br/editais) para conferir todos os processos abertos.`;
    }

    return {
      text,
      editais,
      actions
    };
  }

  // 10. Solicitação de Destaque de Componentes / Onde Fica / Como Fazer na Interface
  const isHighlightIntent = 
    lower.includes('onde') || 
    lower.includes('aonde') || 
    lower.includes('destac') || 
    lower.includes('mostre') || 
    lower.includes('mostrar') || 
    lower.includes('aponte') || 
    lower.includes('indicar') || 
    lower.includes('indica') || 
    lower.includes('como acho') || 
    lower.includes('como faço') || 
    lower.includes('como filtrar') || 
    lower.includes('como pesquisar') || 
    lower.includes('como buscar') || 
    lower.includes('como salvar') || 
    lower.includes('como ver pdf') ||
    lower.includes('onde está') ||
    lower.includes('onde fica');

  if (isHighlightIntent) {
    return handleComponentHighlightEngine(lower);
  }

  // 11. Solicitação de Artigos Científicos Diretos no Chat ou Busca Acadêmica
  const isArticleSearchIntent = 
    lower.includes('artigo') || 
    lower.includes('pesquise') || 
    lower.includes('pesquisa') || 
    lower.includes('busque') || 
    lower.includes('buscar') || 
    lower.includes('encontre') || 
    lower.includes('publica') || 
    lower.includes('paper') || 
    lower.includes('arxiv') || 
    lower.includes('openalex') || 
    lower.includes('crossref') || 
    lower.includes('scielo') || 
    lower.includes('doaj') || 
    lower.includes('resumo de');

  if (isArticleSearchIntent) {
    const cleanQuery = extractCleanAcademicQuery(prompt);
    const searchQuery = cleanQuery || 'integração latino-americana sustentabilidade';

    try {
      const searchRes = await executeFederatedSearch(
        searchQuery,
        ['OpenAlex', 'arXiv', 'DOAJ', 'Europe PMC', 'Crossref', 'Semantic Scholar', 'CORE'],
        true
      );

      const articles = searchRes.articles.slice(0, 5);

      actions.push({
        type: 'HIGHLIGHT_ELEMENT',
        description: `Pesquisou artigos para: "${searchQuery}"`,
        payload: {
          elementId: 'results-feed-column',
          title: 'Resultados Acadêmicos Encontrados',
          description: `Foram localizados artigos científicos reais indexados nas bases federadas.`
        }
      });

      let text = `Executei a busca federada em tempo real nas bases acadêmicas para o termo **"${searchQuery}"**.\n\n` +
        `Localizei **${searchRes.totalFound} publicações**, unificadas e desduplicadas por DOI canônico. `;

      if (articles.length > 0) {
        text += `Aqui estão os principais artigos científicos recuperados diretamente pelas APIs:\n\n`;
        for (const art of articles.slice(0, 3)) {
          const authorNames = art.authors.map(a => a.name).slice(0, 2).join(', ');
          text += `- **${art.title}** (${art.year || 's.d.'}) por *${authorNames}* — Indexado em **${art.sources.join(', ')}**.`;
          if (art.openAccess?.isOpen) text += ` [Acesso Aberto]`;
          if (art.doi) text += ` DOI: [${art.doi}](https://doi.org/${art.doi})`;
          text += `\n`;
        }
        text += `\nVocê pode ler o resumo, ver o PDF ou salvar na sua coleção diretamente nos cartões abaixo:`;
      }

      return {
        text,
        articles,
        actions
      };
    } catch (e: any) {
      console.warn("Federated search error in copilot:", e.message);
    }
  }

  // 12. Notícias ou Informações em Tempo Real do Portal UNILA (https://portal.unila.edu.br/)
  const isPortalNewsIntent = 
    lower.includes('notícia') || 
    lower.includes('noticia') || 
    lower.includes('portal da unila') || 
    lower.includes('portal unila') || 
    lower.includes('novidades') || 
    lower.includes('acontecendo') || 
    lower.includes('evento');

  if (isPortalNewsIntent) {
    const news = await fetchUnilaNews(undefined, 4);
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      description: 'Navegação Institucional do Portal UNILA',
      payload: {
        elementId: 'institutional-horizontal-nav',
        title: 'Portal Institucional UNILA',
        description: 'Acesse o portal oficial em https://portal.unila.edu.br/'
      }
    });

    let text = `Consultei o portal oficial da **UNILA** (https://portal.unila.edu.br/noticias) em tempo real. Veja as notícias e comunicados institucionais mais recentes:\n\n`;
    if (news.length > 0) {
      for (const n of news) {
        text += `📰 **[${n.title}](${n.url})**\n`;
        if (n.summary) text += `> ${n.summary.slice(0, 180)}...\n`;
        if (n.date) text += `*Data: ${n.date}*\n\n`;
      }
    } else {
      text += `Acesse diretamente o portal de notícias em [portal.unila.edu.br/noticias](https://portal.unila.edu.br/noticias) para acompanhar as divulgações da universidade.`;
    }

    return { text, actions };
  }

  // 13. Dúvidas sobre Conceitos Científicos, Metodologia ou Termos Acadêmicos Específicos
  // Aciona a consulta de conceitos SOMENTE se houver termo conceitual explícito (evitando termos banais e saudações)
  const concept = extractConceptTerm(lower);
  if (concept && concept.length >= 3) {
    const scientificData = await fetchScientificConcept(concept);
    if (scientificData && scientificData.extract) {
      return {
        text: `### ${scientificData.title}\n\n${scientificData.extract}\n\n` +
          `*Fonte consultada: [${scientificData.title}](${scientificData.url})*\n\n` +
          `Deseja que eu pesquise artigos científicos completos sobre **${scientificData.title}** nas 8 bases acadêmicas do Multirrepositório?`,
        actions: [{
          type: 'HIGHLIGHT_ELEMENT',
          payload: {
            elementId: 'search-bar-input',
            title: `Pesquisar sobre ${scientificData.title}`,
            description: `Digite "${scientificData.title}" na barra de pesquisa para recuperar a literatura científica completa.`
          }
        }]
      };
    }
  }

  // 14. Fallback Conversacional Dinâmico
  return {
    text: `Entendi sua mensagem: "${prompt}". Como sua copiloto na **UNILA**, posso te apoiar em qualquer dúvida e conectar o que você procura à literatura científica, aos editais oficiais ou ao uso da plataforma. O que você gostaria de explorar agora?`,
    actions: [{
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'search-bar-input',
        title: 'Pesquisa Acadêmica UNILA',
        description: 'Digite palavras-chave, autores ou DOI para iniciar uma busca federada.'
      }
    }]
  };
}

/**
 * Motor de Destaque de Componentes e Orientação da Interface
 */
function handleComponentHighlightEngine(lower: string): {
  text: string;
  actions: CopilotAction[];
} {
  const actions: CopilotAction[] = [];

  // Acesso Aberto (Open Access)
  if (lower.includes('acesso aberto') || lower.includes('open access') || lower.includes('oa') || lower.includes('gratuito') || lower.includes('sem paywall')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'open-access-toggle-btn',
        title: 'Filtro de Acesso Aberto (OA)',
        description: 'Clique neste botão para filtrar exclusivamente artigos com licença livre e sem cobrança de taxa.'
      }
    });
    actions.push({ type: 'SET_OPEN_ACCESS', payload: { value: true } });
    return {
      text: "Destaquei o filtro de **Acesso Aberto (Open Access)** na interface. Ao ativá-lo, o sistema filtra exclusivamente artigos de periódicos livres de paywall (vias Dourada, Verde, Híbrida e Bronze). Já deixei ativado para sua próxima consulta!",
      actions
    };
  }

  // PDF Direto
  if (lower.includes('pdf') || lower.includes('baixar') || lower.includes('download') || lower.includes('texto completo')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'pdf-only-toggle-btn',
        title: 'Filtro Com PDF Direto',
        description: 'Exibe exclusivamente publicações com link direto verificado para leitura e download de PDF.'
      }
    });
    actions.push({ type: 'SET_HAS_PDF', payload: { value: true } });
    return {
      text: "Destaquei o seletor **Com PDF Direto**. Ele garante que você visualize apenas artigos que possuem o arquivo PDF íntegro acessível para download imediato ou leitura no visualizador embutido da aplicação.",
      actions
    };
  }

  // Artigos Salvos / Biblioteca / Favoritos
  if (lower.includes('salvo') || lower.includes('favorito') || lower.includes('coleção') || lower.includes('guardar') || lower.includes('bibtex') || lower.includes('ris')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'saved-articles-btn',
        title: 'Coleção de Artigos Salvos',
        description: 'Acesse suas referências favoritadas e exporte em BibTeX ou RIS para Zotero e Mendeley.'
      }
    });
    actions.push({ type: 'OPEN_SAVED' });
    return {
      text: "Destaquei o botão **Coleção Salva** no cabeçalho e abri o painel de favoritos. Lá ficam guardados todos os artigos que você marcou com a estrela ou marcador, permitindo exportar a bibliografia em lote nos formatos BibTeX e RIS.",
      actions
    };
  }

  // Barra de Pesquisa Principal
  if (lower.includes('barra de busca') || lower.includes('barra de pesquisa') || lower.includes('onde digito') || lower.includes('onde pesquiso') || lower.includes('onde buscar')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'search-bar-input',
        title: 'Barra de Pesquisa Acadêmica',
        description: 'Digite qualquer termo científico, tópico de pesquisa, nome de autor ou código DOI.'
      }
    });
    return {
      text: "Destaquei a **Barra de Pesquisa Acadêmica**. Você pode digitar temas de pesquisa, operadores booleanos (AND, OR), nomes de autores ou códigos DOI. Pressione Enter ou clique na lupa para iniciar a colheita federada nas 8 bases.",
      actions
    };
  }

  // Seletores das 8 Bases
  if (lower.includes('bases') || lower.includes('repositório') || lower.includes('fontes') || lower.includes('arxiv') || lower.includes('openalex') || lower.includes('crossref') || lower.includes('capes') || lower.includes('doaj')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'repository-selectors-bar',
        title: 'Bases Acadêmicas Integradas',
        description: 'Ative ou desative individualmente cada uma das 8 bases conectadas à UNILA.'
      }
    });
    return {
      text: "Destaquei a barra de **Bases a Consultar** logo abaixo do campo de busca. Aqui você pode clicar para ligar ou desligar cada fonte acadêmica (OpenAlex, arXiv, Crossref, Portal CAPES, DOAJ, Europe PMC, Semantic Scholar e CORE).",
      actions
    };
  }

  // Filtros Laterais / Facetas
  if (lower.includes('filtro') || lower.includes('lateral') || lower.includes('ano') || lower.includes('autor') || lower.includes('área') || lower.includes('faceta')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'desktop-filter-sidebar',
        title: 'Filtros Facetados',
        description: 'Refine os resultados por faixa de anos, autores frequentes, áreas do conhecimento e periódicos.'
      }
    });
    return {
      text: "Destaquei a **Barra Lateral de Filtros Facetados** à esquerda. Ela exibe a distribuição quantitativa dos artigos encontrados por ano de publicação, autores com mais publicações, áreas do conhecimento e periódicos acadêmicos.",
      actions
    };
  }

  // Busca Semântica IA
  if (lower.includes('semântic') || lower.includes('semantica') || lower.includes('vetorial') || lower.includes('modo semântico')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'semantic-toggle-btn',
        title: 'Modo de Busca Semântica IA',
        description: 'Combina palavras-chave exatas com busca vetorial contextual.'
      }
    });
    actions.push({ type: 'SET_SEMANTIC_MODE', payload: { value: true } });
    return {
      text: "Destaquei o botão de **Busca Semântica IA**. Quando ativo, o motor do Multirrepositório não se limita a termos literais: ele expande sinônimos conceituais e faz ranqueamento por similaridade contextual.",
      actions
    };
  }

  // Navegação Institucional e Editais
  if (lower.includes('portal') || lower.includes('institucional') || lower.includes('site da unila') || lower.includes('onde fica o edital')) {
    actions.push({
      type: 'HIGHLIGHT_ELEMENT',
      payload: {
        elementId: 'institutional-horizontal-nav',
        title: 'Navegação Institucional UNILA',
        description: 'Acesso direto ao Portal UNILA, Editais Oficiais e Biblioteca Latino-Americana.'
      }
    });
    return {
      text: "Destaquei a barra de **Navegação Institucional UNILA** no topo superior da aplicação. Ela contém atalhos oficiais diretos para o Portal Institucional da UNILA (https://portal.unila.edu.br/), o Portal de Editais e a Biblioteca Latino-Americana.",
      actions
    };
  }

  // Destaque Padrão na Barra de Busca
  actions.push({
    type: 'HIGHLIGHT_ELEMENT',
    payload: {
      elementId: 'search-bar-input',
      title: 'Explorar Recursos da Plataforma',
      description: 'Barra central para busca científica integrada da UNILA.'
    }
  });

  return {
    text: "Destaquei a área principal de pesquisa. Se você deseja encontrar um elemento específico, pergunte: *'onde fica o filtro de acesso aberto?'*, *'onde vejo os artigos salvos?'*, *'como baixar PDFs?'* ou *'onde seleciono as bases acadêmicas?'*.",
    actions
  };
}

function extractSearchKeywords(text: string, stopWords: string[]): string {
  const words = text
    .replace(/[^\w\s-]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !stopWords.includes(w.toLowerCase()));
  return words.slice(0, 4).join(' ');
}

function extractCleanAcademicQuery(prompt: string): string {
  const removePatterns = [
    /^(busque|buscar|pesquise|pesquisar|encontre|ache|mostre|exiba)\s+(artigos?\s+(sobre|de)?|papers?\s+(sobre|de)?)/i,
    /^(artigos?\s+(sobre|de)?)/i,
    /^(quero\s+ver\s+artigos?\s+(sobre|de)?)/i,
    /^(quais\s+(são\s+os\s+)?artigos?\s+(sobre|de)?)/i,
    /\b(no\s+chat|aqui\s+no\s+chat|por\s+favor|pra\s+mim)\b/gi
  ];

  let cleaned = prompt.trim();
  for (const pat of removePatterns) {
    cleaned = cleaned.replace(pat, '').trim();
  }

  return cleaned.replace(/[?.!]+$/, '').trim();
}

function normalizeText(text: string): string {
  return (text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\w\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractConceptTerm(lower: string): string {
  const match = lower.match(/(?:o que [eé]|o que significa|conceito de|defini[çc][aã]o de|explique|como funciona)\s+([a-zA-ZÀ-ÿ\s]{3,40})/i);
  if (match && match[1]) {
    const term = match[1].trim().replace(/(?:na ciência|na pesquisa|acad[eê]mico|\?)/gi, '').trim();
    const conversationalStopWords = [
      'oi', 'ola', 'olá', 'isso', 'aquilo', 'voce', 'você', 'sophia', 'unila',
      'multirrepositorio', 'multirrepositório', 'ajuda', 'pesquisa', 'tudo', 'nada',
      'bom dia', 'boa tarde', 'boa noite', 'um artigo', 'um paper', 'a unila', 'o portal'
    ];
    if (conversationalStopWords.includes(term.toLowerCase()) || term.length < 3) {
      return '';
    }
    return term;
  }
  return '';
}
