import { UnilaEdital } from '../src/types.js';

export interface UnilaNewsItem {
  id: string;
  title: string;
  summary: string;
  url: string;
  date?: string;
  category?: string;
}

export interface UnilaEventItem {
  id: string;
  title: string;
  date: string;
  url: string;
}

/**
 * Busca editais oficiais em tempo real do sistema de documentos e portal da UNILA
 * https://documentos.unila.edu.br e https://portal.unila.edu.br/editais
 */
export async function fetchUnilaEditais(
  query?: string,
  category?: string,
  limit: number = 8
): Promise<UnilaEdital[]> {
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6000);

    const res = await fetch('https://documentos.unila.edu.br/?items_per_page=60', {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
      },
      signal: controller.signal
    });
    clearTimeout(timeout);

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }

    const html = await res.text();
    const editais: UnilaEdital[] = [];

    // Parse do padrão de tabela de editais da UNILA
    const trMatches = [...html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];

    for (let i = 1; i < trMatches.length; i++) {
      const rowHtml = trMatches[i][1];
      const linkMatch = rowHtml.match(/href="([^"]+)"/i);
      const cells = [...rowHtml.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map(m =>
        m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
      );

      if (cells.length >= 7) {
        const number = cells[0] || '';
        const year = cells[1] || '';
        const title = cells[2] || '';
        const isNew = (cells[3] || '').toLowerCase().includes('novo');
        const type = cells[4] || 'Geral';
        const unit = cells[5] || 'UNILA';
        const pubDate = cells[7] || cells[6] || '';
        const updateDate = cells[8] || undefined;

        let relativeUrl = linkMatch ? linkMatch[1] : '';
        if (relativeUrl.startsWith('/')) {
          relativeUrl = `https://documentos.unila.edu.br${relativeUrl}`;
        } else if (!relativeUrl.startsWith('http')) {
          relativeUrl = `https://documentos.unila.edu.br/${relativeUrl}`;
        }

        editais.push({
          id: `edital-${year}-${number}-${i}`,
          number,
          year,
          title,
          category: type,
          unit,
          publishDate: pubDate,
          updateDate,
          url: relativeUrl || 'https://portal.unila.edu.br/editais',
          isNew
        });
      }
    }

    // Filtragem por termo de busca se especificado
    let filtered = editais;
    if (query && query.trim()) {
      const qLower = query.toLowerCase().trim();
      const qTerms = qLower.split(/\s+/).filter(t => t.length > 2);
      filtered = filtered.filter(ed => {
        const fullText = `${ed.number} ${ed.year} ${ed.title} ${ed.category} ${ed.unit}`.toLowerCase();
        return qTerms.some(term => fullText.includes(term));
      });
    }

    if (category && category.trim()) {
      const catLower = category.toLowerCase().trim();
      filtered = filtered.filter(ed =>
        ed.category.toLowerCase().includes(catLower) || ed.unit.toLowerCase().includes(catLower)
      );
    }

    return filtered.slice(0, limit);
  } catch (err: any) {
    console.warn('Erro ao consultar https://documentos.unila.edu.br:', err.message);
    // Retorna conjunto oficial de editais recentes da UNILA como salvaguarda
    return getFallbackUnilaEditais(query);
  }
}

/**
 * Consulta notícias em tempo real no portal institucional da UNILA (https://portal.unila.edu.br/noticias)
 */
export async function fetchUnilaNews(query?: string, limit: number = 5): Promise<UnilaNewsItem[]> {
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6000);

    const res = await fetch('https://portal.unila.edu.br/noticias', {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
      },
      signal: controller.signal
    });
    clearTimeout(timeout);

    if (!res.ok) throw new Error(`HTTP ${res.status}`);

    const html = await res.text();
    const news: UnilaNewsItem[] = [];
    const articleMatches = [...html.matchAll(/<article[^>]*>([\s\S]*?)<\/article>/gi)];

    for (let i = 0; i < articleMatches.length; i++) {
      const artHtml = articleMatches[i][1];
      const titleMatch = artHtml.match(/<h2[^>]*>[\s\S]*?<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/i);
      const descMatch = artHtml.match(/<p class="description"[^>]*>([\s\S]*?)<\/p>/i);
      const dateMatch = artHtml.match(/<time[^>]*>([\s\S]*?)<\/time>/i);

      if (titleMatch) {
        const url = titleMatch[1];
        const title = titleMatch[2].replace(/<[^>]+>/g, '').trim();
        const summary = descMatch ? descMatch[1].replace(/<[^>]+>/g, '').trim() : '';
        const date = dateMatch ? dateMatch[1].replace(/<[^>]+>/g, '').trim() : '';

        news.push({
          id: `news-${i}`,
          title,
          summary,
          url,
          date
        });
      }
    }

    let filtered = news;
    if (query && query.trim()) {
      const qLower = query.toLowerCase();
      filtered = filtered.filter(n =>
        n.title.toLowerCase().includes(qLower) || n.summary.toLowerCase().includes(qLower)
      );
    }

    return filtered.slice(0, limit);
  } catch (err: any) {
    console.warn('Erro ao consultar notícias da UNILA:', err.message);
    return [];
  }
}

/**
 * Consulta conceito científico via API externa (Wikipedia API em Português)
 * para gerar fundamentação 100% dinâmica sem respostas pré-programadas
 */
export async function fetchScientificConcept(term: string): Promise<{
  title: string;
  extract: string;
  url: string;
} | null> {
  const cleanTerm = term.trim();
  if (!cleanTerm || cleanTerm.length < 3) return null;

  // Evita buscar termos banais ou saudações no repositório enciclopédico
  const ignoredTerms = ['oi', 'ola', 'olá', 'opa', 'bom dia', 'boa tarde', 'boa noite', 'ajuda', 'teste', 'tudo bem', 'sophia'];
  if (ignoredTerms.includes(cleanTerm.toLowerCase())) return null;

  try {
    const encoded = encodeURIComponent(cleanTerm);
    const res = await fetch(
      `https://pt.wikipedia.org/api/rest_v1/page/summary/${encoded}`,
      { headers: { 'User-Agent': 'UNILA-Academic-Search/2.0' } }
    );
    if (!res.ok) return null;
    const data = await res.json();
    
    // Se for página de desambiguação, rejeita para evitar respostas desconexas
    if (data.type === 'disambiguation') return null;
    if (data.extract) {
      const lowerExtract = data.extract.toLowerCase();
      if (lowerExtract.includes('pode referir-se a:') || lowerExtract.includes('pode se referir a:') || lowerExtract.includes('desambiguação')) {
        return null;
      }

      return {
        title: data.title,
        extract: data.extract,
        url: data.content_urls?.desktop?.page || `https://pt.wikipedia.org/wiki/${encoded}`
      };
    }
  } catch (e) {
    // Ignora e continua
  }
  return null;
}

